package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.VibrationNetwork;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;public class MechanicalExciterBlock extends Block{public static final IntegerProperty FREQUENCY=IntegerProperty.create("frequency",1,15);public MechanicalExciterBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(FREQUENCY,8));}@Override public MapCodec<MechanicalExciterBlock> codec(){return RedstoneEngineering.MECHANICAL_EXCITER_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FREQUENCY);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos q,boolean m){if(l instanceof ServerLevel sl){int a=l.getBestNeighborSignal(p);if(a>0)VibrationNetwork.propagate(sl,p,a,s.getValue(FREQUENCY));}}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int f=s.getValue(FREQUENCY)%15+1;l.setBlock(p,s.setValue(FREQUENCY,f),Block.UPDATE_CLIENTS);pl.displayClientMessage(Component.literal("Mechanical exciter f="+f+" amplitude=redstone"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}